// Regenerates src/index.ts from the component folders. Each folder's index.ts decides what it exposes;
// internal-only building blocks live in src/internal and are never exported.
import { readdir, writeFile } from "node:fs/promises";

const components = (await readdir("src/components", { withFileTypes: true }))
  .filter((d) => d.isDirectory())
  .map((d) => d.name)
  .sort();
const lines = [
  "// Generated by scripts/gen-index.mjs — run `pnpm --filter datui gen:index` after adding a component folder.",
  ...components.map((c) => `export * from "./components/${c}";`),
  'export * from "./hooks";',
  'export { Portal, type PortalProps, usePortalContainer } from "./lib/portal";',
  'export { SPACING, type SpacingSize } from "./lib/spacing";',
  'export { cn } from "./lib/utils";',
  "",
];
await writeFile("src/index.ts", lines.join("\n"));
console.log(`index: ${components.length} component folders`);
